export function ModelIcon({ name, size = 32, className }: ModelIconProps) {
  const lowerName = name.toLowerCase()
  let IconComponent = null

  if (lowerName.includes('claude') || lowerName.includes('anthropic')) {
    IconComponent = icons.anthropic
  } else if (lowerName.includes('gemini') || lowerName.includes('google')) {
    IconComponent = icons.gemini
  } else if (lowerName.includes('gpt') || lowerName.includes('openai')) {
    IconComponent = icons.openai
  } else if (lowerName.includes('deepseek')) {
    IconComponent = icons.deepseek
  } else if (lowerName.includes('llama') || lowerName.includes('meta')) {
    IconComponent = icons.meta
  } else if (lowerName.includes('mistral')) {
    IconComponent = icons.mistral
  } else if (lowerName.includes('moonshot') || lowerName.includes('kimi')) {
    IconComponent = icons.moonshot
  } else if (lowerName.includes('cohere')) {
    IconComponent = icons.cohere
  } else if (lowerName.includes('perplexity')) {
    IconComponent = icons.perplexity
  } else if (lowerName.includes('grok') || lowerName.includes('xai')) {
    IconComponent = icons.grok
  } else if (lowerName.includes('nvidia')) {
    IconComponent = icons.nvidia
  } else if (lowerName.includes('microsoft') || lowerName.includes('copilot')) {
    IconComponent = icons.microsoft
  } else if (lowerName.includes('hugging')) {
    IconComponent = icons.huggingface
  } else if (lowerName.includes('stability') || lowerName.includes('stable')) {
    IconComponent = icons.stability
  } else if (lowerName.includes('midjourney')) {
    IconComponent = icons.midjourney
  } else if (lowerName.includes('yi') || lowerName.includes('01.ai')) {
    IconComponent = icons.yi
  } else if (lowerName.includes('qwen') || lowerName.includes('alibaba')) {
    IconComponent = icons.qwen
  } else if (lowerName.includes('baichuan')) {
    IconComponent = icons.baichuan
  } else if (lowerName.includes('chatglm') || lowerName.includes('zhipu')) {
    IconComponent = icons.chatglm
  } else if (lowerName.includes('zeroone')) {
    IconComponent = icons.zeroone
  } else if (lowerName.includes('cursor')) {
    IconComponent = icons.cursor
  } else if (lowerName.includes('gemma')) {
    IconComponent = icons.gemma
  } else if (lowerName.includes('manus')) {
    IconComponent = icons.manus
  } else if (lowerName.includes('nous')) {
    IconComponent = icons.nousresearch
  } else if (lowerName.includes('zai') || lowerName.includes('z.ai')) {
    IconComponent = icons.zai
  }

  if (IconComponent) {
    return <IconComponent width={size} height={size} className={className} />
  }

  // Fallback
  return (
    <div className={`flex items-center justify-center bg-gray-100 rounded-full ${className}`} style={{ width: size, height: size }}>
      <Cpu size={size * 0.6} className="text-gray-500" />
    </div>
  )
}